import unittest

def fee_cents(quantity, per_share):
    if type(quantity) is not int or type(per_share) is not int:
        raise ValueError("expected exact integers")
    if quantity < 0 or per_share < 0:
        raise ValueError("expected nonnegative values")
    return quantity * per_share

class FeeTests(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(fee_cents(3, 2), 6)
        self.assertEqual(fee_cents(0, 2), 0)
    def test_invalid(self):
        for value in [True, -1, "3", 3.0]:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    fee_cents(value, 2)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(FeeTests)
result = unittest.TestResult()
suite.run(result)
print(result.testsRun)
print(result.wasSuccessful())

def fee_cents(quantity, per_share):
    return quantity * per_share  # prevalidated nonnegative integers

checked = 0
for a in range(6):
    for b in range(6):
        for rate in range(4):
            if fee_cents(a+b, rate) != fee_cents(a, rate) + fee_cents(b, rate):
                raise AssertionError("additivity failed")
            checked += 1
print(checked)
